    # Helper function to expand a single level of nesting
    def expand_level(text):
        result = ""
        i = 0
        while i < len(text):
            if text[i].isdigit():
                count = int(text[i])
                i += 1
                while i < len(text) and text[i].islower():
                    result += text[i]
                    i += 1
                if i < len(text) and text[i] == ']':
                    return result * count
            else:
                result += text[i]
                i += 1
        return result

    # Main expansion process
    while True:
        new_text = expand_level(text)
        if new_text == text:
            break
        text = new_text

    return text[:2000]

